// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetShop Own shop invoice identity
	// (GET /admin/shop)
	GetShop(ctx context.Context, request GetShopRequestObject) (GetShopResponseObject, error)
	// PatchShop Update shop invoice identity
	// (PATCH /admin/shop)
	PatchShop(ctx context.Context, request PatchShopRequestObject) (PatchShopResponseObject, error)
	// GetInternalTenant Tenant invoice snapshot (service)
	// (GET /internal/tenants/{id})
	GetInternalTenant(ctx context.Context, request GetInternalTenantRequestObject) (GetInternalTenantResponseObject, error)
	// ListTenants List tenants
	// (GET /sysadmin/tenants)
	ListTenants(ctx context.Context, request ListTenantsRequestObject) (ListTenantsResponseObject, error)
	// CreateTenant Create a tenant
	// (POST /sysadmin/tenants)
	CreateTenant(ctx context.Context, request CreateTenantRequestObject) (CreateTenantResponseObject, error)
	// DeleteTenant Delete a tenant
	// (DELETE /sysadmin/tenants/{id})
	DeleteTenant(ctx context.Context, request DeleteTenantRequestObject) (DeleteTenantResponseObject, error)
	// GetTenant Get a tenant
	// (GET /sysadmin/tenants/{id})
	GetTenant(ctx context.Context, request GetTenantRequestObject) (GetTenantResponseObject, error)
	// PatchTenant Change name or contact email
	// (PATCH /sysadmin/tenants/{id})
	PatchTenant(ctx context.Context, request PatchTenantRequestObject) (PatchTenantResponseObject, error)
	// ReplaceTenantHostnames Replace the hostnames and the primary
	// (PUT /sysadmin/tenants/{id}/hostnames)
	ReplaceTenantHostnames(ctx context.Context, request ReplaceTenantHostnamesRequestObject) (ReplaceTenantHostnamesResponseObject, error)
	// ReinstateTenant Reinstate a suspended tenant
	// (POST /sysadmin/tenants/{id}/reinstate)
	ReinstateTenant(ctx context.Context, request ReinstateTenantRequestObject) (ReinstateTenantResponseObject, error)
	// SuspendTenant Suspend a tenant
	// (POST /sysadmin/tenants/{id}/suspend)
	SuspendTenant(ctx context.Context, request SuspendTenantRequestObject) (SuspendTenantResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

